const slots = $slots;
const minutesOf = (clock) => {
  const parts = clock.split(":");
  return Number(parts[0]) * 60 + Number(parts[1]);
};
const lastTicketMinutes = minutesOf(slots.tickets[0].clock) - slots.lastTicketMinutes;
probe(lastTicketMinutes > 0, "the last ticket must fall inside the day");
const slotsClocks = slots.shifts.map((shift) => minutesOf(shift.clock));
const requested = slots.tickets.map((ticket) => minutesOf(ticket.clock));
const successes = requested.filter((minutes) => minutes > 0 && minutes < lastTicketMinutes && slotsClocks.includes(minutes));
if (successes.length !== 1) {
  throw new Error(successes.length + " tickets fall inside the day");
}
const winning = slots.tickets.find((ticket) => minutesOf(ticket.clock) === successes[0]);
probe(winning !== undefined, "the requested ticket must be one of the counter hours");
return "Success: " + winning.day + " " + winning.clock + ".";

